"""A hand-built configs/drivers.yaml for the lineup tests (F17).

The real table is generated by `make fit` from the ingested store, so a test that read it
would be pinned to whatever the last refit produced — and it does not exist at all until
the battery has run. This writes a three-driver table instead: two circuits, two eras, one
cell too thin to publish, and one code the table has never heard of, which between them
exercise all three rungs of the fallback ladder.

It is rendered through `params_writer.render_params` rather than dumped, because the shape
under test is the shape the writer emits — era keys unquoted so they load back as the ints
`scenario.py` indexes with, and every leaf a `(value, origin)` pair.

The configs directory it writes into is a copy of the real one, so a lineup test can
neither read a stale table nor write over the committed constants.
"""

import shutil
from pathlib import Path

from senna import config
from senna.physics.fits.params_writer import render_params

FAST = "VER"        # quickest seat at the fixture circuit, and thin at the second one
SLOW = "HAM"        # slowest seat, same tyre style as FAST so a pace test isolates pace
HEAVY_WEAR = "LEC"  # the only seat carrying a fitted deg_mult away from 1.0
UNKNOWN = "ZZZ"     # never in the table, at any era — the drawn rung of the ladder

# seconds per lap relative to the session mean, centred within each circuit-era fit. The
# gaps are wide for a real grid (0.73 s at Bahrain) so an end-to-end race can show the
# faster seat classifying ahead without a hundred-lap sample.
SEAT_PACE_S = {
    "2026": {
        FAST: {"bahrain_grand_prix": -0.42},  # no Monaco cell: below min_laps_for_seat_pace
        SLOW: {"bahrain_grand_prix": 0.31, "monaco_grand_prix": 0.22},
        HEAVY_WEAR: {"bahrain_grand_prix": 0.11, "monaco_grand_prix": -0.22},
    },
    "2024": {
        FAST: {"bahrain_grand_prix": -0.38},
        SLOW: {"bahrain_grand_prix": 0.26},
        HEAVY_WEAR: {"bahrain_grand_prix": 0.12},
    },
}

SEAT_PACE_MEAN_S = {
    "2026": {FAST: -0.35, SLOW: 0.28, HEAVY_WEAR: -0.02},
    "2024": {FAST: -0.31, SLOW: 0.24, HEAVY_WEAR: 0.09},
}

DEG_MULT = {
    "2026": {FAST: 1.0, SLOW: 1.0, HEAVY_WEAR: 1.18},
    "2024": {FAST: 1.0, SLOW: 1.0, HEAVY_WEAR: 1.12},
}

SEASONS = {"2026": [2026], "2024": [2022, 2023, 2024, 2025]}

HEADER = (
    "# SENNA — driver identity, hand-built for tests/env (F17). Not a fit: the values are\n"
    "# chosen so a reader can predict the assertions, not measured from any race.\n"
)
FITTED = "fitted: tests/env/fixtures/driver_table.py"
STYLISED = "stylised — unidentified, so the pooled curve stands"


def write_driver_configs(destination: Path) -> Path:
    """Copy the live configs into `destination` and drop the fixture table beside them."""
    shutil.copytree(config.REPO_ROOT / "configs", destination)
    tree = {"drivers": {code: _driver(code) for code in SEAT_PACE_MEAN_S["2026"]}}
    text = render_params(tree, generated_at="hand-built fixture", header=HEADER)
    (destination / "drivers.yaml").write_text(text)
    return destination


def _driver(code: str) -> dict:
    entry = {}
    for era, pace_s in SEAT_PACE_S.items():
        identified = DEG_MULT[era][code] != 1.0
        entry[int(era)] = {
            "seat_pace_s": {
                circuit: (value, FITTED) for circuit, value in pace_s[code].items()
            },
            "seat_pace_mean_s": (SEAT_PACE_MEAN_S[era][code], FITTED),
            "deg_mult": (DEG_MULT[era][code], FITTED if identified else STYLISED),
            "deg_mult_identified": (identified, FITTED),
            "deg_mult_se": (0.06 if identified else 0.4, FITTED),
            "n_laps": (2400, FITTED),
            "seasons": (SEASONS[era], FITTED),
        }
    return entry
